import{_ as r}from"./chunks/ai-diagnosis.CeD7Zjye.js";import{_ as d,C as t,o as l,c as h,j as a,a as c,E as s,a6 as o}from"./chunks/framework.CCKCzdWs.js";const g="/diagrams/failure-clustering-semantic-merge.svg",k=JSON.parse('{"title":"AI diagnosis","description":"An LLM you configure explains a failure cluster against your git diff, with a suggested patch checked against your source before you see it. Off by default.","frontmatter":{"title":"AI diagnosis","description":"An LLM you configure explains a failure cluster against your git diff, with a suggested patch checked against your source before you see it. Off by default.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/ai-diagnosis.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/ai-diagnosis.html"}],["meta",{"property":"og:title","content":"AI diagnosis | Piwi for Playwright"}],["meta",{"property":"og:description","content":"An LLM you configure explains a failure cluster against your git diff, with a suggested patch checked against your source before you see it. Off by default."}]]},"headers":[],"relativePath":"features/ai-diagnosis.md","filePath":"features/ai-diagnosis.md","lastUpdated":1795554528000}'),u={name:"features/ai-diagnosis.md"};function p(f,e,m,y,b,w){const i=t("Needs"),n=t("DemoExamples");return l(),h("div",null,[e[0]||(e[0]=a("h1",{id:"ai-diagnosis",tabindex:"-1"},[c("AI diagnosis "),a("a",{class:"header-anchor",href:"#ai-diagnosis","aria-label":'Permalink to "AI diagnosis"'},"​")],-1)),s(i,{reporter:"",llm:""}),e[1]||(e[1]=o('<p>An LLM you configure explains why a <a href="./failure-clusters.html">failure cluster</a>, or one execution, broke, against the code that changed. This page covers the diagnosis (its content, when it runs, what the model receives, how it fares) and the model&#39;s two clustering jobs: titles and semantic merging. Setting up the model is on <a href="/guide/ai-provider.html">AI provider</a>; acting on the result, on <a href="./fix-plans.html">Fix plans</a>.</p><h2 id="enabling-ai-diagnosis" tabindex="-1">Enabling AI diagnosis <a class="header-anchor" href="#enabling-ai-diagnosis" aria-label="Permalink to &quot;Enabling AI diagnosis&quot;">​</a></h2><p>It needs an <a href="/guide/ai-provider.html">AI provider</a>, where providers, model roles and auto-diagnose are set up.</p><h2 id="response-language" tabindex="-1">Response language <a class="header-anchor" href="#response-language" aria-label="Permalink to &quot;Response language&quot;">​</a></h2><p>A diagnosis comes back in the <a href="/guide/ai-provider.html#response-language">response language</a> set for the instance or the project.</p><h2 id="what-a-diagnosis-contains" tabindex="-1">What a diagnosis contains <a class="header-anchor" href="#what-a-diagnosis-contains" aria-label="Permalink to &quot;What a diagnosis contains&quot;">​</a></h2><ul><li><strong>Category</strong> and <strong>confidence</strong></li><li><strong>Root cause</strong>: the most likely explanation</li><li><strong>Evidence</strong>: the signals relied on, each citing a section of the page</li><li><strong>Suggested fix</strong> and <strong>prevention tips</strong></li></ul><figure><img src="'+r+'" alt="The AI diagnosis of a failure cluster on the cluster page"><figcaption>The AI diagnosis of a failure cluster.</figcaption></figure><h2 id="diagnosing-automatically" tabindex="-1">Diagnosing automatically <a class="header-anchor" href="#diagnosing-automatically" aria-label="Permalink to &quot;Diagnosing automatically&quot;">​</a></h2><p>With <strong>auto-diagnose</strong> on (<a href="/guide/ai-provider.html#enabling-ai-diagnosis">AI provider</a>), a finished run&#39;s clusters with no completed or running diagnosis, not ignored, are diagnosed up to a per-run budget, ordered by their representative execution&#39;s top <a href="/reference/clues.html">clue</a>: <strong>no clue</strong> first (the model reasons from scratch), then a weak clue only, then a failure a strong clue explains, newest cluster first on ties. A diagnosis you rated unhelpful takes a slot again once the evidence changed since it ran, once per rating. New clusters also get a short <strong>title</strong> from one batched call per run; otherwise a cluster is named from its error kind, locator, route and spec file, such as <code>Timeout on getByLabel(&#39;Email address&#39;) in checkout.spec.ts</code>.</p><h2 id="watching-it-stream" tabindex="-1">Watching it stream <a class="header-anchor" href="#watching-it-stream" aria-label="Permalink to &quot;Watching it stream&quot;">​</a></h2><p>The model&#39;s reasoning streams into a live panel with a stage indicator (<em>Researching patterns</em> while a <a href="/guide/ai-provider.html#model-roles">research model</a>, when one is configured, pre-analyzes the failure, then <em>Diagnosing root cause</em>), and turns into the result card when it completes. The <a href="https://piwitests.dev/demo/settings/api" target="_blank" rel="noreferrer">API docs</a> (<code>/settings/api</code> on your instance) describe its protocol.</p><h2 id="diagnosing-one-execution" tabindex="-1">Diagnosing one execution <a class="header-anchor" href="#diagnosing-one-execution" aria-label="Permalink to &quot;Diagnosing one execution&quot;">​</a></h2><p>On an <a href="./evidence.html#one-execution-diagnosis-first">execution page</a>, the <strong>Diagnosis</strong> section of <strong>More ways to fix</strong> shows the cluster&#39;s diagnosis summary and patch with an <strong>Open</strong> link; without one, it diagnoses that execution alone, with the same panel and model. Execution and cluster diagnoses are stored apart; one never overwrites the other. A stored diagnosis stays on screen with no provider configured; with no result and no provider, <strong>Copy prompt</strong> copies the exact request, trimmed to the <a href="/guide/ai-provider.html#context-limits-and-token-cost">context limits</a>, for your own AI tool.</p><h2 id="scm-grounded-context" tabindex="-1">SCM-grounded context <a class="header-anchor" href="#scm-grounded-context" aria-label="Permalink to &quot;SCM-grounded context&quot;">​</a></h2><p>The diagnosis is fed the code that changed. On a cluster page, <strong>pin a baseline commit</strong> (the diff from it to the run), <strong>cherry-pick commits</strong> (their full diffs), and <strong>preview the exact context</strong> before running it. Unpinned, the diff starts at the last green run before the cluster first appeared, else the last run before it where this test passed; the preview names which. When the host lists only part of a large diff (its newest commits, its first files), or the patches are cut to budget, the section is marked truncated. With the repository reachable (<a href="/guide/source-control.html">Source control</a>), the <strong>full current content</strong> of the most suspect changed files and of the failing test&#39;s local imports (page objects, helpers, fixtures) is sent too, capped by <code>PIWI_AI_MAX_SOURCE_FILES</code> (default 4) and <code>PIWI_AI_MAX_SOURCE_FILE_CHARS</code>.</p><p>When the failing tests recorded <a href="./server-coverage.html">coverage</a>, the context lists their <a href="/guide/concepts.html#suspect-lines">suspect lines</a>, the changed lines they ran, ranked by how many passing tests of the run ran them too; their files&#39; patches come first within the budget.</p><h3 id="validated-patches" tabindex="-1">Validated patches <a class="header-anchor" href="#validated-patches" aria-label="Permalink to &quot;Validated patches&quot;">​</a></h3><p>Every suggested patch is dry-run, hunk by hunk, against the source files the model was shown, and carries one badge: <strong>Applies cleanly</strong>, <strong>Applies with offset</strong> (<code>git apply</code> should still succeed), <strong>Does not apply</strong> (the file diverged), <strong>Invalid diff</strong>, or <strong>Unverified</strong> (the file was not in the context). When a fix is <a href="./failure-clusters.html#did-the-fix-work">verified</a>, the patch is checked again at the fix&#39;s commit. The model is told to return no patch unless it can quote the lines it changes. Applying one is always yours (<a href="./fix-plans.html#the-next-step">the actions</a>); only <a href="./auto-heal.html">auto-heal</a> writes to your repository, with deterministic locator edits.</p><h2 id="diagnoses-written-by-an-agent" tabindex="-1">Diagnoses written by an agent <a class="header-anchor" href="#diagnoses-written-by-an-agent" aria-label="Permalink to &quot;Diagnoses written by an agent&quot;">​</a></h2><p>A coding agent can record its own diagnosis on a cluster or one failure with the MCP tool <code>record_diagnosis</code> (on one failure, the <a href="https://piwitests.dev/demo/settings/api" target="_blank" rel="noreferrer">REST API</a> too), in the JSON a model returns here. It needs no provider, its patch is validated against the failing commit&#39;s source when <a href="/guide/source-control.html">source control</a> is connected, and the panel shows it <strong>written by an agent</strong> with the model it named. It replaces the current diagnosis (kept in the history). Declining the <strong>Agent diagnoses</strong> capability refuses them; declining AI diagnosis does not.</p><p>For one failure, <code>run_execution_diagnosis</code> runs the page&#39;s diagnosis and <code>get_execution_diagnosis</code> reads the stored one, whoever wrote it.</p><h2 id="locator-healing" tabindex="-1">Locator healing <a class="header-anchor" href="#locator-healing" aria-label="Permalink to &quot;Locator healing&quot;">​</a></h2><p>For a broken locator, the context holds <a href="./locator-healing.html">Locator healing</a>&#39;s ranked replacements and recommended fix, which the model is told to use rather than invent one.</p><h2 id="fix-plans" tabindex="-1">Fix plans <a class="header-anchor" href="#fix-plans" aria-label="Permalink to &quot;Fix plans&quot;">​</a></h2><p>The diagnosis, its patch, the locator fix, the top five suspect lines and the verify command form a <a href="./fix-plans.html">fix plan</a>.</p><h2 id="diagnosis-history" tabindex="-1">Diagnosis history <a class="header-anchor" href="#diagnosis-history" aria-label="Permalink to &quot;Diagnosis history&quot;">​</a></h2><p>A re-diagnose keeps the previous result; a nightly sweep keeps the newest 20 per cluster (<code>PIWI_RETENTION_DIAGNOSIS_VERSIONS</code>, <code>0</code> keeps all). <strong>History</strong> in the panel header lists them newest first, with model, category, confidence and token cost, and what changed since each. A re-diagnose sends the model the previous category, confidence, summary and root cause, the triage note, and, when you rated it unhelpful, your note and an instruction not to repeat it without new evidence. The new diagnosis starts unrated; the history keeps the old one&#39;s thumbs.</p><p>A diagnosis is flagged <strong>may be stale</strong> only when the evidence changed since it ran <strong>and</strong> the cluster is still failing; the banner says whether new occurrences or new evidence caused it.</p><h2 id="how-diagnoses-fare" tabindex="-1">How diagnoses fare <a class="header-anchor" href="#how-diagnoses-fare" aria-label="Permalink to &quot;How diagnoses fare&quot;">​</a></h2><p><strong>AI usage</strong> in Settings → AI (<a href="/guide/ai-provider.html#usage-and-quality">what it counts</a>) also says how each model&#39;s diagnoses fared:</p><ul><li><strong>Rated helpful</strong>: thumbs up over every rating, from 10 ratings (below, the panel says the sample is too small);</li><li><strong>Patches that apply</strong>: suggested patches that <a href="#validated-patches">apply</a>, over every patch that could be checked;</li><li><strong>Verified by the fix</strong>: diagnoses whose cluster a change to the files they named fixed;</li><li><strong>Regressed</strong>: verified diagnoses whose failure came back.</li></ul><p>Agent diagnoses get their own row, under the model the agent named. Each diagnosis stores a hash of the instructions it was written under (<code>promptSha</code> in its details), telling apart diagnoses before and after a change to the custom instructions or the language. Piwi never switches models on these numbers; <a href="./analytics.html#hand-back-outcomes">Analytics</a> shows the ratings across projects.</p><h2 id="custom-instructions" tabindex="-1">Custom instructions <a class="header-anchor" href="#custom-instructions" aria-label="Permalink to &quot;Custom instructions&quot;">​</a></h2><p><strong>Global</strong> instructions (Settings → AI) and <strong>per-project</strong> ones (Project → Settings → AI diagnosis) describe your architecture, common false positives or house style for fixes.</p><h2 id="context-limits-and-token-cost" tabindex="-1">Context limits (and token cost) <a class="header-anchor" href="#context-limits-and-token-cost" aria-label="Permalink to &quot;Context limits (and token cost)&quot;">​</a></h2><p>Each input sent to the model is capped to keep diagnoses fast and affordable; the caps are set on the <a href="/guide/ai-provider.html#context-limits-and-token-cost">AI provider</a> page.</p><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h2><p>API keys are encrypted at rest with <a href="/reference/configuration.html#general"><code>PIWI_SECRET_KEY</code></a>. A diagnosis sends the bounded context above to your provider; for local analysis, use Ollama or another self-hosted OpenAI-compatible model.</p><h2 id="semantic-merging-optional" tabindex="-1">Semantic merging (optional) <a class="header-anchor" href="#semantic-merging-optional" aria-label="Permalink to &quot;Semantic merging (optional)&quot;">​</a></h2><p>With <strong>Semantic clustering</strong> on (Settings → AI) and an embedding model, a semantic layer sits on top of the <a href="./failure-clusters.html#how-failures-are-grouped">fingerprint</a>. After a run, its new clusters are embedded and compared (cosine similarity) with the project&#39;s other open clusters; near-duplicates above <code>PIWI_CLUSTER_SIMILARITY_THRESHOLD</code> (default <code>0.92</code>) are merged into the longest-lived cluster (<a href="./failure-clusters.html#how-failures-are-grouped">what the survivor keeps</a>), and a fingerprint alias sends future occurrences to it. This catches one root cause phrased differently enough to dodge the fingerprint. The text is cleaned first (ANSI codes, framework stack frames, volatile tokens), and older clusters are embedded a few at a time over the runs that follow.</p><p>Pairs in the <strong>ambiguous band</strong>, between <code>PIWI_CLUSTER_SUGGEST_THRESHOLD</code> (default <code>0.80</code>) and the merge threshold, go to a model, which judges the error text, locators, most-affected tests and overlap: a confident yes merges, a less confident yes becomes a <strong>merge suggestion</strong> (Clusters view of the project&#39;s Failures tab) for a Maintainer or above to approve or dismiss, and a no stays apart. Without AI, or past five model calls in a run, the pair becomes a suggestion. This runs after every run that <a href="/reference/test-metadata.html#run-origin">sends notifications</a>, independently of auto-diagnose.</p><p>Each pair is judged once: the model&#39;s no is kept. A pair someone dismissed, or <a href="#split-a-cluster-by-hand">split by hand</a>, is never merged automatically, however close the score.</p><figure><img src="'+g+'" alt="Diagram of the semantic merging flow: clusters are embedded, compared by cosine similarity, and kept apart, adjudicated by a model, or merged depending on the score"><figcaption>The cosine score decides between keeping two clusters apart, asking a model (or a person), and merging them.</figcaption></figure><h3 id="split-a-cluster-by-hand" tabindex="-1">Split a cluster by hand <a class="header-anchor" href="#split-a-cluster-by-hand" aria-label="Permalink to &quot;Split a cluster by hand&quot;">​</a></h3><p>Moving tests out of a cluster needs no AI: see <a href="./failure-clusters.html#split-a-cluster-by-hand">Failure clusters</a>.</p><h2 id="try-it-in-the-demo" tabindex="-1">Try it in the demo <a class="header-anchor" href="#try-it-in-the-demo" aria-label="Permalink to &quot;Try it in the demo&quot;">​</a></h2><p>The <a href="https://piwitests.dev/demo/" target="_blank" rel="noreferrer">live demo</a> needs no provider: some clusters carry a diagnosis with a validated patch, the others stream a simulated one.</p>',48)),s(n),e[2]||(e[2]=o('<h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/recipes/mass-failure.html">Triage a run gone red</a>: clusters first, then a diagnosis</li><li><a href="./failure-clusters.html">Failure clusters</a>: grouping, and whether the fix worked</li><li><a href="/guide/privacy.html">Privacy &amp; data flow</a>: what a diagnosis sends, and where</li><li><a href="./notifications.html">Notifications &amp; alerts</a>: <code>diagnosis.completed</code> and the cluster events</li><li><a href="/features/mcp.html">MCP server</a>: clusters and diagnoses for agents</li><li><a href="./deployed-environments.html">Deployed environments</a></li></ul>',2))])}const _=d(u,[["render",p]]);export{k as __pageData,_ as default};
